package cache

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"regexp"
	"strings"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type Role int

const (
	RoleReader Role = iota
	RoleWriter
	RoleAdmin
)

type CacheEntry struct {
	Key       string      `bson:"key"`
	Value     interface{} `bson:"value"`
	Owner     string      `bson:"owner"`
	Namespace string      `bson:"namespace"`
	TTL       time.Time   `bson:"ttl"`
}

type UserSession struct {
	UserID    string
	Role      Role
	Namespace string
}

type DistributedCache struct {
	client     *mongo.Client
	collection *mongo.Collection
}

func NewDistributedCache(uri string) (*DistributedCache, error) {
	client, err := mongo.Connect(context.Background(), options.Client().ApplyURI(uri))
	if err != nil {
		return nil, err
	}
	coll := client.Database("dcache").Collection("entries")
	return &DistributedCache{client: client, collection: coll}, nil
}

func (dc *DistributedCache) hashKey(namespace, key string) string {
	h := sha256.New()
	h.Write([]byte(fmt.Sprintf("%s:%s", namespace, key)))
	return hex.EncodeToString(h.Sum(nil))
}

func (dc *DistributedCache) validateAccess(session *UserSession, requiredRole Role) error {
	if session == nil {
		return fmt.Errorf("unauthorized: no session")
	}
	if session.Role < requiredRole {
		return fmt.Errorf("forbidden: insufficient role")
	}
	return nil
}

func (dc *DistributedCache) buildNamespaceFilter(session *UserSession) bson.M {
	if session.Role == RoleAdmin {
		return bson.M{}
	}
	return bson.M{"namespace": session.Namespace}
}

func (dc *DistributedCache) normalizeQueryKey(input string) string {
	trimmed := strings.TrimSpace(input)
	return trimmed
}

func (dc *DistributedCache) Get(ctx context.Context, session *UserSession, key string) (*CacheEntry, error) {
	if err := dc.validateAccess(session, RoleReader); err != nil {
		return nil, err
	}

	nsFilter := dc.buildNamespaceFilter(session)
	normalizedKey := dc.normalizeQueryKey(key)

	filter := bson.M{"key": normalizedKey}
	for k, v := range nsFilter {
		filter[k] = v
	}
	filter["ttl"] = bson.M{"$gt": time.Now()}

	var entry CacheEntry
	err := dc.collection.FindOne(ctx, filter).Decode(&entry)
	if err != nil {
		return nil, fmt.Errorf("cache miss: %w", err)
	}
	return &entry, nil
}

func (dc *DistributedCache) Put(ctx context.Context, session *UserSession, key string, value interface{}, ttl time.Duration) error {
	if err := dc.validateAccess(session, RoleWriter); err != nil {
		return err
	}

	hashedKey := dc.hashKey(session.Namespace, key)
	entry := CacheEntry{
		Key:       hashedKey,
		Value:     value,
		Owner:     session.UserID,
		Namespace: session.Namespace,
		TTL:       time.Now().Add(ttl),
	}

	opts := options.Update().SetUpsert(true)
	filter := bson.M{"key": hashedKey, "namespace": session.Namespace}
	update := bson.M{"$set": entry}
	_, err := dc.collection.UpdateOne(ctx, filter, update, opts)
	return err
}

var safePatternRegex = regexp.MustCompile(`^[a-zA-Z0-9_\-.*]+$`)

func (dc *DistributedCache) Search(ctx context.Context, session *UserSession, pattern string) ([]*CacheEntry, error) {
	if err := dc.validateAccess(session, RoleReader); err != nil {
		return nil, err
	}

	if !safePatternRegex.MatchString(pattern) {
		return nil, fmt.Errorf("invalid search pattern")
	}

	nsFilter := dc.buildNamespaceFilter(session)
	queryFilter := dc.buildSearchFilter(regexp.QuoteMeta(pattern), nsFilter)

	cursor, err := dc.collection.Find(ctx, queryFilter)
	if err != nil {
		return nil, err
	}
	defer cursor.Close(ctx)

	var results []*CacheEntry
	for cursor.Next(ctx) {
		var entry CacheEntry
		if err := cursor.Decode(&entry); err != nil {
			continue
		}
		results = append(results, &entry)
	}
	return results, nil
}

func (dc *DistributedCache) buildSearchFilter(pattern string, nsFilter bson.M) bson.M {
	filter := bson.M{"ttl": bson.M{"$gt": time.Now()}}
	for k, v := range nsFilter {
		filter[k] = v
	}
	filter["key"] = bson.M{"$regex": pattern}
	return filter
}

func (dc *DistributedCache) Delete(ctx context.Context, session *UserSession, key string) error {
	if err := dc.validateAccess(session, RoleWriter); err != nil {
		return err
	}

	hashedKey := dc.hashKey(session.Namespace, key)
	filter := bson.M{"key": hashedKey, "namespace": session.Namespace}
	_, err := dc.collection.DeleteOne(ctx, filter)
	return err
}
